import{createMatch,startGame,DEFAULT_RULES,buildDeck,computeResult,sortHand,rankOrder,isWild,applyTribute,completeReturn,classify,applyMove}from'@gd/engine';
import{toVisibleRoot}from'../../review6/visible-world';
export function nativeGiftFixture(suit:'S'|'C'){const match=createMatch({...DEFAULT_RULES},963),prev=computeResult([0,3,1,2],[2,2],DEFAULT_RULES);match.lastResult=prev;match.lastHead=0;match.levels=[...prev.levelsAfter];match.gameNo=1;const s=startGame(match),deck=buildDeck(),spade=deck.find(c=>c.id===12)!,club=deck.find(c=>c.id===51)!,returned=deck.find(c=>c.id===26)!,higher=deck.filter(c=>!isWild(c,s.ctx)&&rankOrder(c.rank,s.ctx)>rankOrder(14,s.ctx));const reserved=new Set([...higher,spade,club,returned].map(c=>c.id)),fill=deck.filter(c=>!reserved.has(c.id)&&c.rank!==14).slice(0,15),head=[...higher,returned,club,...fill],used=new Set(head.map(c=>c.id)),giver=[spade,...deck.filter(c=>!used.has(c.id)&&c.id!==spade.id&&c.rank<=13&&c.rank!==3).slice(0,26)],taken=new Set([...head,...giver].map(c=>c.id)),rest=deck.filter(c=>!taken.has(c.id));s.hands=[head,rest.slice(0,27),giver,rest.slice(27)];if(suit==='C'){s.hands[0][s.hands[0].findIndex(c=>c.id===51)]=spade;s.hands[2][s.hands[2].findIndex(c=>c.id===12)]=club;}s.hands.forEach(sortHand);s.pendingReturns=[];s.tribute=null;s.tribute=applyTribute(s,[0,1,2,3])!;s.leader=s.tribute.leader;s.lastPlayer=s.leader;s.turn=s.pendingReturns[0].from;completeReturn(s,s.hands[0].find(c=>c.id===26)!);const history:any[]=[];function play(move:any){const priorTarget=s.lastCombo,events=applyMove(s,move);history.push({events,priorTarget});}play({pass:false,combo:classify([s.hands[2].find(c=>c.id===26)!],s.ctx,s.match.opts)[0]});play({pass:true});return{s,history,obs:toVisibleRoot(s,history)};}
